const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const telefono = String(body.telefono || '').trim();
const fecha_actual = String(body.fecha_actual || '').trim();
const hora_actual = String(body.hora_actual || '').trim();
const nueva_fecha = String(body.nueva_fecha || '').trim();
const nueva_hora = String(body.nueva_hora || '').trim();

// Formatear fechas para mensajes
const fechaObjActual = new Date(fecha_actual + 'T00:00:00');
const fechaObjNueva = new Date(nueva_fecha + 'T00:00:00');
const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const diaSemanaActual = diasSemana[fechaObjActual.getUTCDay()];
const diaMesActual = fechaObjActual.getUTCDate();
const mesActual = meses[fechaObjActual.getUTCMonth()];

const diaSemanaNueva = diasSemana[fechaObjNueva.getUTCDay()];
const diaMesNueva = fechaObjNueva.getUTCDate();
const mesNuevo = meses[fechaObjNueva.getUTCMonth()];

// Ventanas de búsqueda
const fechaInicioDiaActual = new Date(fecha_actual + 'T00:00:00').toISOString();
const fechaFinDiaActual = new Date(fecha_actual + 'T23:59:59').toISOString();

// Calcular fecha fin para el nuevo hueco (asumimos 60 min por defecto)
const nuevaFechaInicio = new Date(`${nueva_fecha}T${nueva_hora}:00`);
const nuevaFechaFin = new Date(nuevaFechaInicio.getTime() + 60 * 60000);

return [{ json: {
  telefono,
  fecha_actual,
  hora_actual,
  nueva_fecha,
  nueva_hora,
  diaSemanaActual,
  diaMesActual,
  mesActual,
  diaSemanaNueva,
  diaMesNueva,
  mesNuevo,
  fechaInicioDiaActual,
  fechaFinDiaActual,
  nuevaFechaInicio: nuevaFechaInicio.toISOString(),
  nuevaFechaFin: nuevaFechaFin.toISOString()
}}];

const eventos = $('Google Calendar - Buscar Evento').all();
const datos = $('Parsear Argumentos').first().json;

// Buscar evento que coincida con la hora actual
const eventoEncontrado = eventos.find(e => {
  const start = e.json.start?.dateTime || e.json.start?.date;
  if (!start) return false;
  const horaEvento = start.split('T')[1]?.substring(0, 5);
  return horaEvento === datos.hora_actual;
});

if (!eventoEncontrado) {
  return [{
    json: {
      error: true,
      mensaje: 'No encontré esa cita en el calendario. ¿Estás seguro de la fecha y hora?'
    }
  }];
}

return [{ json: {
  ...datos,
  evento_id: eventoEncontrado.json.id,
  evento_summary: eventoEncontrado.json.summary,
  calendar_id: eventoEncontrado.json.organizer?.email || 'primary'
}}];

const eventosOcupados = $('Google Calendar - Verificar Nuevo Hueco').all();
const datos = $('Filtrar Evento por Hora').first().json;

if (eventosOcupados.length > 0) {
  return [{
    json: {
      error: true,
      disponible: false,
      mensaje: 'El nuevo horario ya está ocupado. ¿Quieres probar con otra hora?'
    }
  }];
}

return [{ json: {
  ...datos,
  disponible: true
}}];

const updateResult = $('Google Calendar - Actualizar Evento').first().json;
const datos = $('Verificar Disponibilidad').first().json;

if (updateResult.id) {
  const mensaje = `Listo, tu cita ha quedado cambiada del ${datos.diaSemanaActual} ${datos.diaMesActual} de ${datos.mesActual} a las ${datos.hora_actual} al ${datos.diaSemanaNueva} ${datos.diaMesNueva} de ${datos.mesNuevo} a las ${datos.nueva_hora}.`;

  return [{
    json: {
      modificado: true,
      resumen_nuevo: `${datos.evento_summary} - ${datos.diaSemanaNueva} ${datos.diaMesNueva} de ${datos.mesNuevo} a las ${datos.nueva_hora}`,
      mensaje: mensaje,
      google_calendar_event_id: updateResult.id,
      html_link: updateResult.htmlLink
    }
  }];
} else {
  return [{
    json: {
      modificado: false,
      error: 'No se pudo actualizar el evento',
      mensaje: 'Hubo un problema al modificar tu cita. Por favor, llama al salón.'
    }
  }];
}
